import{at as e,it as t,n,vt as r}from"./chunks/framework.yntlMcNk.js";var i=JSON.parse(`{"title":"Portal","description":"","frontmatter":{"title":"Portal"},"headers":[],"relativePath":"api/reference/portal.md","filePath":"api/reference/portal.md"}`),a={name:`api/reference/portal.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="portal" tabindex="-1">Portal <a class="header-anchor" href="#portal" aria-label="Permalink to “Portal”">​</a></h1><div><p>Operations of the tag <strong>Portal</strong> implemented in this release. Generated from <code>api/openapi.yaml</code>; planned operations are not listed.</p><h2 id="listPortalCatalogs" tabindex="-1">Shared catalogs of the portal (SCR-050) <a class="header-anchor" href="#listPortalCatalogs" aria-label="Permalink to “Shared catalogs of the portal (SCR-050)”">​</a></h2><p><code>GET /portal/catalogs</code> · <code>listPortalCatalogs</code></p><p>The catalogs with scope <code>instance</code>, ordered by name (case-insensitive). Personal catalogs never appear in the portal, not even the caller&#39;s own.</p><p><strong>Access</strong>: permission <code>portal:read</code></p><h3 id="responses" tabindex="-1">Responses <a class="header-anchor" href="#responses" aria-label="Permalink to “Responses”">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Description</th><th>Problem types</th></tr></thead><tbody><tr><td>200</td><td>Shared catalogs</td><td>–</td></tr><tr><td>401</td><td>Not authenticated (missing, expired or revoked credentials or session). When a previously valid session or refresh token was presented and has ended, the header <code>OEA-Purge-Local-Data: session-ended</code> is set and the problem <code>type</code> is <code>urn:oea:problem:session-ended</code>.</td><td><code>urn:oea:problem:session-ended</code></td></tr><tr><td>403</td><td>Authenticated, but a permission declared in <code>x-oea-authorization</code> is missing, a separation-of-duties rule forbids the action (e.g. self-administration, SoD-1), or a privileged role is not effective because the session lacks a second factor (SoD-8). The problem body is generic and does not reveal the missing permission. A session created with a temporary password answers every operation except <code>GET /me</code>, the logout, <code>POST /me/password</code> and <code>POST /me/password/suggestion</code> with problem type <code>urn:oea:problem:password-change-required</code> (REQ-173 AC2). A session that must enroll a second factor answers every operation except <code>GET /me</code>, the logout, <code>GET /me/second-factors</code> and the TOTP and passkey enrollment with problem type <code>urn:oea:problem:second-factor-enrollment-required</code> (US-031 AC2). If the principal holds no effective role at all, the header <code>OEA-Purge-Local-Data: access-revoked</code> is set.</td><td><code>urn:oea:problem:password-change-required</code>, <code>urn:oea:problem:second-factor-enrollment-required</code></td></tr><tr><td>429</td><td>Rate limit or throttling exceeded (REQ-186, REQ-168), problem type <code>urn:oea:problem:too-many-requests</code>; <code>Retry-After</code> gives the seconds until the next request is accepted. Nothing was processed.</td><td><code>urn:oea:problem:too-many-requests</code></td></tr></tbody></table><h2 id="queryPortalCatalog" tabindex="-1">Query a shared catalog read-only (SCR-050) <a class="header-anchor" href="#queryPortalCatalog" aria-label="Permalink to “Query a shared catalog read-only (SCR-050)”">​</a></h2><p><code>GET /portal/catalogs/{id}/query</code> · <code>queryPortalCatalog</code></p><p>One page of rows of a catalog with scope <code>instance</code>, with the catalog&#39;s configured columns, default sort and default join mode. The result equals that of the catalog query (<code>queryCatalog</code>) without filters, join mode overrides or view, including its visibility rules: only properties with visibility <code>public</code> appear (REQ-124, REQ-160) and soft-deleted entities are not returned. <code>page</code>, <code>pageSize</code>, <code>sort</code>, <code>cursor</code> and the query time limit (503 <code>query-timeout</code>) behave as in the catalog query. A personal catalog is answered with 404, like a catalog that does not exist, also for its creator.</p><p><strong>Access</strong>: permission <code>portal:read</code></p><h3 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>In</th><th>Required</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>path</td><td>yes</td><td>string (uuid)</td><td>–</td></tr><tr><td><code>page</code></td><td>query</td><td>no</td><td>integer</td><td>–</td></tr><tr><td><code>pageSize</code></td><td>query</td><td>no</td><td>integer</td><td>–</td></tr><tr><td><code>sort</code></td><td>query</td><td>no</td><td>string</td><td><code>{field}:{asc|desc}</code>, multiple comma-separated</td></tr><tr><td><code>cursor</code></td><td>query</td><td>no</td><td>string</td><td>The <code>nextCursor</code> of the previous page, sent together with <code>page</code> set to that page&#39;s number + 1 (REQ-071). The page then starts after the last row of the previous one instead of skipping rows. The cursor is valid only for the same query (catalog, columns or view, sort, join modes, filters, page size) and only until the backend restarts or the catalog changes; otherwise the query is answered with 400 <code>cursor</code> and the client repeats it without the cursor.</td></tr></tbody></table><h3 id="responses-1" tabindex="-1">Responses <a class="header-anchor" href="#responses-1" aria-label="Permalink to “Responses”">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Description</th><th>Problem types</th></tr></thead><tbody><tr><td>200</td><td>One page of catalog rows</td><td>–</td></tr><tr><td>400</td><td>Invalid paging, sort or cursor parameters (problem type <code>urn:oea:problem:validation-failed</code>), e.g. an unknown sort column, a sort on a column the reader may not read, a page size above 200 or a cursor of another query; <code>invalidFields</code> names the rejected parameters.</td><td><code>urn:oea:problem:validation-failed</code></td></tr><tr><td>401</td><td>Not authenticated (missing, expired or revoked credentials or session). When a previously valid session or refresh token was presented and has ended, the header <code>OEA-Purge-Local-Data: session-ended</code> is set and the problem <code>type</code> is <code>urn:oea:problem:session-ended</code>.</td><td><code>urn:oea:problem:session-ended</code></td></tr><tr><td>403</td><td>Authenticated, but a permission declared in <code>x-oea-authorization</code> is missing, a separation-of-duties rule forbids the action (e.g. self-administration, SoD-1), or a privileged role is not effective because the session lacks a second factor (SoD-8). The problem body is generic and does not reveal the missing permission. A session created with a temporary password answers every operation except <code>GET /me</code>, the logout, <code>POST /me/password</code> and <code>POST /me/password/suggestion</code> with problem type <code>urn:oea:problem:password-change-required</code> (REQ-173 AC2). A session that must enroll a second factor answers every operation except <code>GET /me</code>, the logout, <code>GET /me/second-factors</code> and the TOTP and passkey enrollment with problem type <code>urn:oea:problem:second-factor-enrollment-required</code> (US-031 AC2). If the principal holds no effective role at all, the header <code>OEA-Purge-Local-Data: access-revoked</code> is set.</td><td><code>urn:oea:problem:password-change-required</code>, <code>urn:oea:problem:second-factor-enrollment-required</code></td></tr><tr><td>404</td><td>Resource not found, or an existence-sensitive resource the caller may not see (same response for both cases, REQ-159)</td><td>–</td></tr><tr><td>429</td><td>Rate limit or throttling exceeded (REQ-186, REQ-168), problem type <code>urn:oea:problem:too-many-requests</code>; <code>Retry-After</code> gives the seconds until the next request is accepted. Nothing was processed.</td><td><code>urn:oea:problem:too-many-requests</code></td></tr><tr><td>503</td><td>The query took longer than the configured time limit (<code>oea.catalog.query-timeout</code>, 10 seconds by default) and was cancelled (problem type <code>urn:oea:problem:query-timeout</code>, REQ-186, REQ-071). Nothing was changed; narrowing the filters or the joins makes the query cheaper.</td><td><code>urn:oea:problem:query-timeout</code></td></tr></tbody></table></div>`,2)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};